  S = `게임 업데이트`,
  C = `신규 콘텐츠, 기능 변경, 버그 수정과 같은 크고 작은 업데이트를 플레이어들에게 알립니다.`,
  w = `개발자와 교류하고 대화하고 질문할 수 있는 이벤트에 팬들을 초대합니다.`,
  T = `게임이 출시되었음을 플레이어들에게 알립니다.`,
  E = `플레이어들에게 토너먼트, 개발자의 라이브 스트리밍, 유명 스트리머의 게임 플레이를 시청하도록 권장합니다.`,
  D = `일부 플레이어에게만 영향을 주는 소규모의 수정이나 변경에 가장 적합합니다.`,
  O = `매주, 격주, 매월 등 정기적으로 진행되는 보통 규모의 전형적인 기능 업데이트에 가장 적합합니다.`,
