  F = `기간 한정 아이템 또는 희귀하거나 특별한 전리품을 찾을 기회를 공지합니다. 또는 플레이어의 참여도에 따라 전리품의 개수를 늘립니다.`,
  I = `플레이어들에게 과제를 완료하고 커뮤니티 이벤트에 참여하여 게임의 기간 한정 보너스 및 혜택을 받을 수 있도록 알립니다.`,
