  R = `아트워크, 창작마당 출품 또는 멀티플레이 대전과 같이, 콘테스트에 참가하기 위해 어떤 행동을 취하도록 팬들에게 요청합니다.`,
  z = `팬들을 오프라인 교류 이벤트에 초대하거나, 본인이 어딘가 흥미로운 장소로 향하고 있다는 사실을 팬들에게 알립니다.`,
  B = `뉴스가 될 만한 이야기를 플레이어들에게 전해주세요. 중요한 업적을 달성했나요? 무언가 흥미로운 작업을 진행 중인가요?`,
