  H = `Steam 사용자가 게임, DLC, 또는 게임 내 콘텐츠를 한정된 기간에 무료로 플레이할 수 있도록 합니다. 무료 주말, 게임 체험판, 그 외 다른 기간 한정 콘텐츠 이용 이벤트가 여기에 해당합니다.`,
  U = `새로운 시즌 패스 또는 전투 패스의 출시에 대해 설명해 주세요. 이 기간은 일반적으로 추가 콘텐츠, 혜택 또는 하위 이벤트를 포함하는 주 또는 월 단위의 기간입니다.`,
  W = `출시 예정인 다른 게임이나 게임이 출시될 다른 플랫폼에 관해 이야기하려면 이 카테고리를 사용세요. 게시물이 다른 게임이나 플랫폼 또는 상점에 관한 내용이라면, 이 카테고리만 사용해야 합니다.`,
