  K = `핼러윈 테마의 기간 한정 시각 효과를 사용해 특별한 게임 내 이벤트를 진행하세요.`,
  q = `제작자 홈(개발사, 배급사 또는 프랜차이즈 페이지)를 맞춤 설정하세요. 가장 최근에 공개된 제작자 홈이 표시됩니다.`,
