  ne = `라이브 스트리밍 이벤트는 Steam 방송 또는 외부 스트리밍 사이트를 지정할 수 있으며, 일정 시작 시간 및 종료 시간을 정의할 수 있습니다. Steam 방송은 상점 페이지와 Steam 홈페이지에 표시됩니다.`,
