  ae = `게임과 DLC, 게임 내 콘텐츠 할인 및 프로모션을 위한 카테고리입니다. 게임을 소유하고 있지 않은 사용자에게 게임 할인을 공지하거나, 기존 플레이어에게 게임 내 할인에 대해 알립니다.`,
