  Ye = `'라이브러리 집중 조명 배너'를 생성해 게임의 라이브러리 상세 페이지에서 이 이벤트를 강조해 표시하는 것을 권장합니다.`,
  Xe = `이벤트 시작 날짜 및 종료 날짜 필수`,
