  et = `신규: Steam 어워드 후보작 추천`,
  tt = `게임이 올해의 Steam 어워드 후보작에 오를 수 있도록 팬에게 추천을 요청하세요.(이 카테고리는 후보작 추천이 끝날 때까지만 사용 가능)`,
  nt = `이 게시물은 Steam 라이브러리 홈페이지에 표시되지 않습니다`,
  rt = `신규: Steam 어워드 투표 요청`,
