  st = `+ 기본적으로 이러한 게시물은 추천 게시물로 표시되며 게임 라이브러리 페이지 상단에 고정됩니다.`,
  ct = `Steam Next Fest 특별 이벤트`,
  lt = `Steam Next Fest 더 알아보기`,
  ut = `선택 사항: Steam Next Fest 기간 중 다음과 같은 이벤트 유형을 최대 두 개까지 만들 수 있습니다.`,
