  gt = `귀하는 Valve 지원으로서 변경 한도 제한 우회가 허용됩니다. 이벤트를 대신 설정하고 게시해야 합니다.`,
  _t = `Steam Next Fest: 간단한 소개`,
  vt = `이 게시글을 통해 Steam 고객에게 개발팀에 대한 이야기, 체험판의 내용 및 게임과의 연관성에 대한 흥미로운 정보를 제공하세요. 제공된 정보는 Steam 상점 페이지와 Next Fest 페이지의 게임 목록에 표시됩니다.`,
  yt = `Steam Next Fest: 실시간 스트리밍`,
  bt = `한 번 선택하면 팬들에게 게임의 라이브 스트리밍 소식을 알리고 팬들이 시청하도록 할 수 있습니다. 이 이벤트는 Steam Next Fest의 공식 캘린더와 게임 페이지에 자동으로 공개됩니다.`,
  xt = `Steam Next Fest: 업무 시간`,
  St = `팬들이 여러분과 여러분의 팀에 연락하여 질문하고 대화할 수 있는 시간을 선택하세요. Steam 채팅, Discord, Reddit AMA, 또는 다른 선호 플랫폼에서 편안하게 채팅과 질의응답하는 이벤트를 만들어 보세요.`,
  Ct = `그룹 공지`,
  wt = `그룹 멤버 전용 뉴스`,
  Tt = `이 게시물은 그룹 홈페이지에만 표시됩니다`,
  Et = `공개 뉴스 게시물`,
  Dt = `그룹 멤버 및 이 큐레이터를 팔로우하는 사람들을 위한 뉴스`,
  Ot = `할인 이벤트`,
  kt = `제작자 홈에서 게임의 할인 랜딩 페이지를 만드세요.`,
  At = `이 게시물은 그룹 홈페이지 및 팔로워의 맞춤 뉴스 허브에 표시됩니다.`,
  jt = `노출 수: %1$s, 읽은 횟수: %2$s`,
  Mt = `노출 수: %1$s`,
  Nt = `열람 횟수: %1$s`,
  Pt = `이벤트 일정 위젯을 사용하면 예정 이벤트 브라우저에 할인 페이지를 심어서 포함할 수 있게 됩니다. 따라서 할인 페이지에서 추천된 게임을 추가적으로 노출할 수 있으며, 게임 특정 이벤트를 생성하여 할인 기간 동안 Steam 고객과의 소통 기회를 마련할 수도 있습니다. 예를 들어, 방송 및 채팅은 개발자들이 Steam 고객과 소통하는 방법입니다.`,
  Ft = `일정에 표시되도록 허용할 이벤트 유형을 하나 이상 선택해야 합니다.`,
  It = `일정의 날짜 범위를 선택합니다. 이는 이벤트 날짜와 동일할 수도 있고 이 이벤트가 향후 일정을 공지하는 경우 달라질 수도 있습니다.`,
  Lt = `기본 설정으로 이 할인 페이지에는 이벤트의 출처인 %1$s가 포함됩니다. 이는 할인 페이지 관리자만 볼 수 있으며 이 할인 페이지가 공개되는 즉시 모두에게 표시됩니다.`,
  Rt = `뉴스 허브`,
  zt = `%1$s가지 이벤트 유형이 사용 중입니다`,
  Bt = `%1$s가지 이벤트 유형이 사용 중입니다`,
  Vt = `위젯에서 체험판 제공하기`,
  Ht = `이 기능을 사용하면 게임 세부 정보 및 마우스 올리기 동작을 제공할 때 체험판 플레이 동작이 선호됩니다. 이렇게 하면 예정된 날짜 범위의 체험판 시작 이벤트도 표시됩니다.`,
  Ut = `이벤트 시작 일시 설정`,
  Wt = `이벤트 종료 일시 설정`,
  Gt = `포함된 이벤트:`,
  Kt = `포함된 앱이 참가할 수 있는 모든 이벤트를 일정에 표시`,
  qt = `기본 그룹이 참가할 수 있는 모든 이벤트와 트랙의 모든 이벤트가 항상 일정에 표시됩니다. 이 확인란에 체크 표시를 하면 포함된 앱이 참가할 수 있는 모든 이벤트도 일정에 표시됩니다. 체크 표시를 선택 해제하면 이벤트를 주최하는 커뮤니티 그룹과 관련된 이벤트 또는 트랙에 명시적으로 표시된 이벤트만 일정에 표시됩니다.`,
  Jt = `경고: 일정 시작 시간이 이벤트 시작 시간 이전입니다. 해당 시간이 정말 올바른가요?`,
  Yt = `계속 진행할까요?`,
  Xt = `계속 진행할까요? 저장되지 않은 변경 사항을 모두 잃게 됩니다.`,
  Zt = `이벤트 편집기`,
  Qt = `이벤트 편집`,
