  rn = `미게시`,
  an = `비공개`,
  on = `공개`,
  sn = `Steam 사용자가 이벤트를 볼 수 있습니다. 이 이벤트에 대한 공개 여부 설정은 변경할 수 없으므로, 이벤트를 숨기려면 이벤트를 삭제해야 합니다.`,
  cn = `미등록 및 공개`,
  ln = `바로 가기 링크가 있는 Steam 사용자는 이벤트를 볼 수 있습니다. 이 이벤트에 대한 공개 여부 설정은 변경할 수 없으므로, 이벤트를 숨기려면 이벤트를 삭제해야 합니다.`,
  un = `조정 대기 중인 라이브러리 공개 상태`,
  dn = `%1$s까지 비공개`,
  fn = `준비 완료, 이벤트가 %1$s에 시작될 때까지 비공개`,
  pn = `이 이벤트는 게시 완료되었으나, 지정된 일시 전까지 비공개 처리되었습니다. 이제 다른 작업은 필요하지 않습니다. 이벤트는 지정하신 시점에 귀사의 Steam 고객에게 자동으로 공개됩니다.`,
  mn = `이 이벤트는 이벤트 시작 날짜에 자동으로 공개됩니다.`,
  hn = `이 이벤트는 이벤트가 시작되기 전인 %1$s에 자동으로 공개됩니다.`,
  gn = `이 이벤트들은 앞으로 진행이 예정된 이벤트이며, 시작 날짜 전에는 공개되지 않도록 설정되어 있습니다. 다른 작업은 필요하지 않습니다. `,
  _n = `비공개, 미게시`,
  vn = `이 이벤트는 아직 초안 모드입니다. 귀사의 커뮤니티 팀 멤버 외에는 아무도 이 이벤트를 볼 수 없습니다. 모든 변경 사항은, 이벤트를 공개로 설정하기 전까지 계속해서 비공개 처리됩니다.`,
  yn = `RSS 피드에 의해 게시되었습니다. RSS 관리자를 열려면 클릭하세요.`,
  bn = `할인 페이지`,
  xn = `공개된 이벤트 URL:`,
  Sn = `언어`,
  Cn = `드롭다운 메뉴에서 언어를 선택하면 해당 언어에 대한 문자 영역을 볼 수 있고 수정할 수 있습니다. 여러 언어를 한 번에 설정하려면 내보내기 및 불러오기 옵션을 사용하세요.`,
  wn = `선택된 언어 없음`,
  Tn = `할인 페이지를 게시하려면 할인 페이지에 대한 맞춤 URL을 설정해야 합니다. 맞춤 URL은 고객이 이용할 수 있는 할인에 대한 URL을 만들 때 사용됩니다.`,
  En = `업데이트 랜딩 페이지를 게시하려면 해당 페이지에 대한 맞춤 URL을 설정해야 합니다. 맞춤 URL은 고객이 이용할 수 있는 URL을 만들 때 사용됩니다.`,
  Dn = `할인 미리 보기`,
  On = `페이지 미리 보기`,
  kn = `이벤트 미리 보기`,
  An = `공지 미리 보기`,
  jn = `라이브 이벤트 보기`,
  Mn = `제작자 홈 보기`,
  Nn = `이벤트 편집`,
  Pn = `키 아트워크`,
  Fn = `상단에 큰 이미지를 사용해 이벤트 및 공지를 브랜딩하세요`,
  In = `아래에서 이미지를 끌어서 설정하거나, 선택기를 사용해 새로운 이미지를 업로드하세요`,
  Ln = `1920px x 620px`,
