  Vn = `공지 제목`,
  Hn = `내부용 제목`,
  Un = `이벤트 세부 정보`,
  Wn = `세부 정보`,
  Gn = `설명`,
  Kn = `공개 여부`,
  qn = `섹션 제목`,
  Jn = `사전 번역된 목록에서 제목을 선택하여 이 섹션 상단에 표시하거나 '맞춤 제목'을 선택하여 원하는 제목을 입력하세요. 필드에 입력을 시작하면 사전 번역된 제목이 표시됩니다.`,
  Yn = `부제`,
  Xn = `(최대 %1$s자. 이벤트 또는 공지 세부 정보 페이지의 상단에 표시됩니다.)`,
  Zn = `(최대 %1$s자 도달. 이벤트 또는 공지 세부 정보 페이지의 상단에 표시됩니다.)`,
  Qn = `제작자 홈 v2를 사용하면 개발사, 배급사, 프렌차이즈 페이지를 유연하게 맞춤 설정할 수 있습니다.`,
  $n = `이 페이지는 공개되지 않았습니다. 페이지를 먼저 게시한 후 현재 제작자 홈으로 설정할 수 있습니다.`,
  er = `이 페이지는 현재 제작자 홈으로 <1>설정되어 있지 않습니다</1>. 이 페이지를 활성화하려면 <2>제작자 홈 대시보드</2>를 사용하세요.`,
  tr = `이 페이지는 현재 제작자 홈으로 설정되어 있습니다. <1>제작자 홈 대시보드</1>에서 페이지를 관리할 수 있습니다.`,
  nr = `아바타`,
  rr = `편집: <1>제작자 페이지 편집기</1>`,
  ir = `소개 문구`,
  ar = `편집: <1>제작자 홈 대시보드</1>`,
  or = `환영합니다!`,
  sr = `<1>게임</1> - 게임은 아래의 연결된 앱 목록에 표시되며 바로 사용할 수 있습니다. 아래에 섹션을 추가하고 게임, DLC, 체험판, 사운드트랙을 필요에 따라 원하는 방식으로 구성하세요.`,
  cr = `<1>게임 연결</1> - 아래 목록에서 누락된 게임이 있다면 게임을 제작자 홈페이지와 연결해야 합니다. 게임을 제작자 홈페이지와 연결하는 방법은 <2>개발사 및 배급사 홈페이지</2> 문서를 참고해 주세요.`,
  lr = `<1>기본 섹션</1> - 아래에는 인기 게임, 추천 게임, 신규 출시 게임을 강조하는 몇 가지 기본 섹션이 이미 구성되어 있습니다. 원하는 대로 기본 섹션을 자유롭게 활용하세요.`,
  ur = `자세한 정보는 관련 문서를 참고하세요.`,
  dr = `카테고리: %1$s`,
  fr = `이벤트 복제 오류`,
  pr = `복제 준비 과정에서 오류가 발생했습니다: %1$s`,
  mr = `이벤트 게시 오류`,
  hr = `이벤트 게시 준비 과정에서 오류가 발생했습니다: %1$s`,
  gr = `해당 할인 이벤트에는 연결된 제품이 많아 제품 정보를 바탕으로 관련 태그를 다시 생성하고 있습니다. 잠시만 기다려 주세요.`,
  _r = `해당 할인 이벤트의 제품 관련 태그를 상점에서 다시 생성할 수 없어 편집기를 안정적으로 열 수 없습니다. 페이지를 새로고침하여 다시 시도해 주세요.`,
  vr = `할인 이벤트와 연결된 제품 중 %1$s개를 상점에서 불러오는 데 실패했습니다. 대부분 판매가 금지되었거나 더 이상 판매되지 않는 제품일 가능성이 높습니다. 이러한 제품에 대한 태그(%2$s)는 다시 생성되지 않았으므로 태그 필터가 적용된 섹션에 표시되지 않을 수 있습니다. 만약 해당 제품이 판매 금지 상태이거나 더 이상 판매되지 않는 제품이라면 이 메시지를 무시하고 계속 작업을 진행하실 수 있습니다.`,
  yr = `이벤트 시작 날짜`,
  br = `공지 날짜`,
  xr = `지금 - 이벤트가 게시된 즉시`,
  Sr = `지금 - 공지가 게시된 즉시`,
  Cr = `예정 - 이벤트가 나중에 시작되도록 설정`,
  wr = `예정 - 공지가 나중에 발표되도록 설정`,
  Tr = `예약된 시작 날짜`,
  Er = `예정된 게시 날짜`,
  Dr = `플레이어들에게 이벤트가 다가오고 있다는 사실을 알리고 알림을 설정하도록 허용하고 싶다면, 이벤트 시작 날짜 이전에 이벤트가 공개되도록 설정하면 됩니다.`,
  Or = `플레이어들에게 이벤트가 다가오고 있다는 사실을 알리고 알림을 설정하도록 허용하고 싶다면, 이벤트 시작 날짜 이전에 공지가 공개되도록 설정하면 됩니다.`,
  kr = `이벤트 종료 날짜`,
  Ar = `이 이벤트 카테고리에는 보통 종료 날짜가 있습니다.`,
  jr = `Steam에서 이벤트가 종료되었음을 표시할 시점을 알 수 있도록 종료일을 선택해 주세요. 이 작업은 Steam이 귀사에서 최근 또는 현재 진행 중인 다른 이벤트를 우선적으로 표시하는 것을 허용하기 위해 필요합니다.`,
  Mr = `시작 날짜 이후 일정 시간이 지나면 종료합니다.`,
