  Pr = `종료 날짜`,
  Fr = `편집기에 표시되는 이벤트 시간은 본인의 현지 시간대입니다. Steam 고객들에게는 각 고객의 현지 시간대로 표시됩니다.`,
  Ir = `지정된 시간에 종료...`,
  Lr = `본인의 현지 시간대를 입력하세요. 이 시간대는 각 고객의 현지 시간대로 자동 전환되어 표시됩니다.`,
  Rr = `자동 알림`,
  zr = `이벤트의 시작 날짜를 미래로 지정하고 팬들에게는 더 빨리 공개되도록 설정하면, 팬들은 이벤트 시작 알림을 수신할 수 있습니다. Steam에서는 사용자의 환경 설정에 따라 푸시 알림 및 이메일을 자동으로 보냅니다.`,
  Br = `인증된 이메일이 있고 %1$s 설치가 완료된 계정에만 테스트 알림이 전송됩니다.`,
