  Qo = `부제는 최대 %1$s자까지 문자만 입력할 수 있으며 BBCode 등 다른 형식은 지원하지 않습니다. 이 부제는 이벤트 및 공지 상세 페이지의 제목과 함께 사용됩니다.`,
  $o = `이벤트 개요는 최대 %1$s자까지 입력할 수 있으며, 텍스트만 가능합니다. 이벤트 목록이나 이벤트 집중 조명에 표시되면 제목 아래에 개요가 나타납니다. 제공된 개요가 없으면, Steam에서 각 언어로 된 설명의 시작 부분에서 텍스트를 가져와 자동으로 생성합니다.`,
