  fs = `집중 조명 기능을 사용하기 전에, 적어도 영어로 된 집중 조명 이미지가 '%1$s' 탭에 할당되어 있는지 확인해 주세요.`,
  ps = `자동 텍스트를 표시할까요?`,
  ms = `이벤트의 제목과 부제가 어두운 오버레이와 함께 이미지의 오른쪽 상단에 자동 표시됩니다.`,
  hs = `이 이벤트는 일시적으로 각 사용자의 활동 섹션 위에 표시됩니다. 이벤트가 항상 게임 상세 페이지에 표시되지 않도록 이벤트 간 적절한 간격을 두고 주요 이벤트에만 사용해야 합니다.`,
