  _s = `Steam 라이브러리의 '새로운 업데이트' 섹션에는 플레이 시간 및 기타 요소를 기반으로 플레이어에게 게시물이 표시됩니다.`,
  vs = `라이브러리 게임 상세 페이지에 표시`,
