  bs = `라이브러리에 게임을 가지고 있는 Steam 사용자와 상점 제품 페이지를 방문하는 사용자에게 표시될 내용에 대해 주의하세요. 예를 들어, 게임 구매를 위한 다른 상점의 링크를 포함하는 것은 문제가 될 수 있습니다. 또한 %1$s을 준수해야 합니다.`,
