  js = `Steam China에 표시하기`,
  Ms = `Steam China의 사용자에게 이벤트가 공개되지 않는 것이 기본 설정입니다. 이벤트가 공개되게 하려면 이 옵션을 활성화 해야 합니다.`,
  Ns = `Steam에서 숨기기`,
  Ps = `Steam China에 표시되는 이벤트의 경우, 이 옵션을 사용하여 전 세계 사용자에게 이벤트를 표시하지 않도록 설정할 수 있습니다`,
  Fs = `복제하려는 이벤트에 다음 언어로 된 콘텐츠가 있습니다. 복제된 이벤트에서 계속 사용할 언어를 확인란에서 선택하세요.`,
  Is = `대부분의 경우 기존 언어를 복제하는 것은 좋지 않습니다.`,
