  Gs = `배경을 세로로 반복`,
  Ks = `배경을 모든 방향으로 반복`,
  qs = `단일 이미지, 표지 및 흐림 처리`,
  Js = `회전식 섹션 화살표 색상`,
  Ys = `배경색 또는 배경 이미지가 매우 밝은 경우 화살표가 잘 보이지 않을 수 있습니다. 이 설정을 사용하여 회전식 섹션 화살표의 기본 색상을 흰색에서 다른 색상으로 변경할 수 있습니다.`,
  Xs = `배경색 또는 배경 이미지가 너무 밝으면 화살표가 잘 보이지 않을 수 있습니다. 이 설정을 사용하여 회전식 섹션 탐색 아이콘의 기본 설정인 흰색과 회색을 변경할 수 있습니다. 이 설정은 주로 Steam Deck을 포함한 작은 디스플레이를 사용할 때 표시됩니다.`,
  Zs = `체험판 정보 불러오는 중`,
  Qs = `이 게시물을 공유할 수 있는 출시된 체험판이 없습니다.`,
