  ec = `이벤트나 공지가 게시되면 체험판의 라이브러리 페이지에 표시됩니다. 체험판만 가지고 있는 플레이어와 소통하도록 해줍니다. `,
  tc = `테마 이벤트: %1$s`,
  nc = `2022 핼러윈`,
  rc = `이 이벤트가 2022 핼러윈을 기념한 게임 업데이트에 관한 이벤트인가요? 핼러윈을 맞아 새로운 맵과 스킨, 아트워크 등 여러 콘텐츠를 게임에 추가하시거나 오싹한 특별 콘텐츠나 도전 과제 또는 다른 비슷한 활동을 기간 한정 이벤트로 진행하시는 경우, 저희에게 알려주세요. 저희는 테마 이벤트를 더욱더 넓은 고객층에 효과적으로 알릴 수 있는 방법을 고민하고 있지만, 이를 위해서는 먼저 개발자들이 연휴나 공휴일을 기념하기 위해 게임에서 어떤 종류의 활동을 진행하는지 더 잘 알아야 할 필요가 있습니다. 이 이벤트가 2022 핼러윈을 기념한 게임 업데이트에 관한 이벤트인 경우 아래의 '켜기'를 클릭하세요.`,
  ic = `핼러윈 테마 이벤트`,
  ac = `핼러윈 테마의 이벤트를 진행하거나 콘텐츠를 추가할 예정이신가요? 게임 내 핼러윈 테마 이벤트로 Steam 스크림에 참여하는 방법에 대한 더 자세한 내용은 %1$s에서 확인하세요.`,
  oc = `Steam 스크림 핼러윈 이벤트 문서`,
  sc = `새로운 DLC 또는 게임에 추가된 콘텐츠`,
  cc = `게임에 핼러윈 테마를 영구 확장`,
  lc = `핼러윈을 테마로 한 게임 내 기간 한정 이벤트를 공지합니다. 이 이벤트에서 플레이어에게 추가 아이템, 보너스, 혜택, 보상, 경험치 등을 줄 수 있습니다. 이러한 이벤트에는 시작 시간과 종료 시간이 있습니다.`,
  uc = `Steam 어워드 후보작 부문`,
  dc = `팬에게 추천을 요청할 특정 부문을 선택해 주세요. 이렇게 하면, 팬이 이벤트에서 해당 부문에 바로 게임을 추천할 수 있습니다!`,
  fc = `올해 Steam 어워드의 거의 모든 부문은(지난 %2$s년 Steam 어워드 후보 추천 이후) %1$s년에 출시된 게임만 추천 대상에 포함됩니다. 귀사의 게임은 그 이전에 출시되었기 때문에 '어버이의 은혜' 부문에만 참가할 수 있습니다.`,
  pc = `더 자세한 정보가 궁금하거나 마케팅에 사용할 아트 템플릿이 포함된 Steam 어워드 자산 키트를 다운로드하려면 <1>이 문서</1>를 확인하세요.`,
  mc = `이 게임은 Steam 어워드 카테고리에 적합하지 않습니다. 문제가 있다고 판단되면, <1>Steamworks 고객지원</1>에 문의해 주세요.`,
  hc = `공개되지 않은 상점 페이지 확인`,
  gc = `앱 ID %1$s의 상점 페이지가 현재 공개되지 않은 상태입니다. 이 이벤트를 게시하면 사용자들이 이 게임에 대해 알게 됩니다. 그래도 이 이벤트를 게시하려면 여기에서 반드시 명시적으로 확인한 후 진행할 수 있습니다.`,
