  al = `교차 프로모션 섹션에서만 할인 로고 표시`,
  ol = `할인 페이지와 포인트 상점 페이지에는 로고를 표시하지 않습니다. 해당 할인에 대한 교차 프로모션을 진행하는 다른 페이지에는 로고가 표시됩니다.`,
  sl = `이 할인 페이지에는 로고가 표시되지 않습니다. 해당 할인에 대한 교차 프로모션을 진행하는 다른 페이지에만 표시됩니다.`,
  cl = `상점 캡슐`,
  ll = `이러한 캡슐을 사용하면 상점에서 일반적으로 게임을 표시하는 위치(회전식 특집 및 추천 게임 캡슐, 상점 허브 및 장바구니 등)에 해당 할인 페이지를 소개할 수 있습니다. 해당 캡슐의 크기는 게임 상점 페이지의 그래픽 자산 탭에 업로드하는 것과 동일합니다.`,
  ul = `모든 캡슐 이미지를 한 번에 업로드할 수 있습니다. 이미지 크기가 캡슐의 규격과 정확히 일치하면 해당 캡슐에 자동으로 지정됩니다. 그 외의 이미지는 직접 지정해야 하며, 필요에 따라 이미지 자르기 작업을 수행하라는 메시지가 표시됩니다. 이미지 파일 이름 끝에 언어 이름을 추가하면 해당 언어용 이미지로 자동 분류됩니다(예: main_capsule_french.jpg).`,
  dl = `할인 이벤트의 브랜딩을 강조하세요. 로고가 선명하게 식별되고 가독성이 높아야 합니다.`,
  fl = `상점 전반의 추천 섹션과 다양한 소형 추천 배너 영역에 표시됩니다.`,
  pl = `이러한 영역은 크기가 작기 때문에 로고는 가장 작은 크기에서도 알아보기 쉬워야 합니다.`,
  ml = `상점 전반과 장바구니 목록에 사용됩니다.`,
  hl = `할인을 홍보하는 데 사용되는 이미지입니다. 인용문, 평가 점수 또는 수상 경력은 포함하지 마세요.`,
  gl = `메인 페이지 상단의 회전식 특집 및 추천 게임 캡슐에 표시됩니다.`,
  _l = `할인을 홍보하는 데 사용되는 수직 자산입니다. 인용문, 평가 점수 또는 수상 경력은 포함하지 마세요.`,
  vl = `계절 할인 기간 중 메인 페이지 상단 및 기타 할인 페이지에 표시될 수 있습니다.`,
  yl = `라이브러리 히어로 이미지`,
  bl = `라이브러리 자산이 최신 버전이 아닙니다. 해당 자산은 모든 고객들에게 공개되므로, 꼭 시간을 내어 업데이트하시기 바랍니다.`,
  xl = `이메일 전체 이미지`,
