  Pl = `할인 페이지 로고를 클릭하면 사용자가 상점의 다른 곳(예: 메인 페이지)으로 이동할 수 있습니다.`,
  Fl = `상점 홈페이지 주소 뒤에 다음 부분만 입력하고, 앞의 슬래시(/)는 포함하지 마세요. 예를 들어 https://store.steampowered.com/category/pins_pegs로 연결하려면 category/pins_pegs를 입력하세요.`,
  Il = `이는 상점 홈페이지를 기준으로 한 상대 경로만 입력해야 하므로, 'https://store.steampowered.com/' 부분은 포함하지 마세요. 예를 들어 https://store.steampowered.com/category/pins_pegs 대신 category/pins_pegs를 입력하세요.`,
  Ll = `맨 앞의 슬래시(/)를 제거하세요. 예를 들어 /category/pins_pegs 대신 category/pins_pegs를 입력하세요.`,
