  Zl = `요청을 처리하는 도중 예기치 않은 오류가 발생했습니다. 나중에 다시 시도해 주세요.`,
  Ql = `이미지 유형이 올바르지 않습니다. 아트워크는 JPG 및 PNG 파일만 지원됩니다.`,
  $l = `아트워크 이미지를 찾을 수 없습니다. 이미지를 다시 업로드하세요.`,
  eu = `제한된 계정입니다. 제한된 계정은 이벤트 내용을 저장할 수 없습니다. 더 자세한 정보는 링크(https://help.steampowered.com/faqs/view/71D3-35C2-AD96-AA3A)를 참고해 주세요.`,
  tu = `섹션이 비공개로 표시됩니다. 배경 그룹 이미지 편집을 위한 미리 보기를 표시 중입니다.`,
  nu = `섹션이 %1$s까지 비공개로 표시됩니다. 배경 그룹 이미지 편집을 위한 미리 보기를 표시 중입니다.`,
  ru = `섹션이 %1$s 이후에 비공개로 표시됩니다. 배경 그룹 이미지 편집을 위한 미리 보기를 표시 중입니다.`,
  iu = `허용된 국가 목록에 포함되어 있지 않으므로 섹션이 비공개로 표시됩니다. 배경 그룹 이미지 편집을 위한 미리 보기를 표시 중입니다.`,
  au = `사용자가 패키지를 소유하고 있지 않으므로 섹션이 비공개로 표시됩니다. 배경 그룹 이미지 편집을 위한 미리 보기를 표시 중입니다.`,
  ou = `사용자가 해당 하드웨어 기기를 사용하지 않았으므로 섹션이 비공개로 표시됩니다. 배경 그룹 이미지 편집을 위한 미리 보기를 표시 중입니다.`,
  su = `'%1$s' 유형의 이 섹션은 미리 보기 모드에서 렌더링되지 않습니다. 그룹 배경 이미지 편집을 위해 사용되는 임시 섹션입니다.`,
  cu = `미리 보기 모드: 할인 페이지 교차 프로모션이 설정되지 않았습니다.`,
  lu = `미리 보기 모드: 할인 페이지 교차 프로모션을 위한 할인 페이지가 유효하지 않거나 불러올 수 없습니다.`,
  uu = `복사 완료!`,
