  eg = `Steam 제품 페이지 할인 배너`,
  tg = `%1$s부터 %2$s까지 제품 페이지 배너 표시`,
  ng = `할인 배너를 할인 탭에 제공하여 배너가 Steam 제품 페이지의 맨 위에 표시되고 해당 게임을 할인 페이지에서 다시 참조할 수 있도록 할 수 있습니다. 이는 Steam 고객이 찜 목록 이메일이나 상점 검색을 통해 특정 게임 할인을 발견하고, 더 큰 할인 이벤트를 검색하는 데 도움이 됩니다. 이러한 배너는 이벤트 시작부터 종료 시까지, 또는 2주 동안만 표시됩니다. 이벤트 시작 및 종료 날짜는 옵션 탭에서 지정할 수 있습니다.`,
  rg = `알림: 게임이나 개발사, 배급사를 팔로우하는 플레이어들에게 보내는 이메일`,
  ig = `여기에는 이 게임과 관련된 개발사 페이지와 배급사 페이지, 프랜차이즈 페이지의 모든 팔로워가 포함됩니다.`,
