  pg = `맞춤 설정된 Steam 클라이언트 마케팅 메시지에서 이 이벤트를 볼 것으로 예상되는 플레이어의 수입니다. Steam 클라이언트 마케팅 메시지는 Steam 데스크톱 클라이언트 실행 시 나타나는 팝업창이며, 관련 Steam 할인 및 흥미로운 이벤트 정보가 표시됩니다.`,
