  yy = `본인은 Valve가 할인 페이지를 수정할 권한을 보유한다는 점을 이해합니다. Valve의 권한은 페이지에서 게임과 방송의 노출, 이벤트 문구 및 이벤트 설명 이미지를 포함하며 이에 국한되지 않습니다.`,
