  xy = `개발사 또는 배급사의 허가를 받은 게임만 할인 페이지에 추가할 수 있다는 점을 인지합니다. 게임을 이 페이지에 추가하면 해당 게임의 개발사가 게임이 할인에 포함되었다는 것을 즉시 확인할 수 있습니다.`,
