  Lb = `유효하지 않음`,
  Rb = `올바르지 않은 크기`,
  zb = `이미지를 잘라 %1$sx%2$s 크기로 조정하려면 아래를 클릭하세요`,
  Bb = `선택하신 이미지가 해당 이미지 유형에 비해 너무 작습니다. 최소 %1$sx%2$s의 크기여야 합니다.`,
  Vb = `히어로 이미지 변경`,
  Hb = `이미지 자르기`,
  Ub = `이미지 자르기 - %1$sx%2$s`,
  Wb = `파란색 상자의 모서리 또는 가장자리를 끌어서, 이벤트 또는 공지에 사용하고 싶은 이미지의 공간을 선택하세요.`,
  Gb = `이미지 크기 조정 열기`,
  Kb = `자른 후 계속 진행`,
  qb = `제공된 이미지가 %1$s 형식과 일치하지 않습니다`,
  Jb = `유효하지 않은 이미지 형식이 선택되었습니다`,
  Yb = `이미지는 정확히 %1$sx%2$s의 해상도여야 합니다`,
  Xb = `함께 업로드되는 이미지의 해상도는 반드시 동일해야 합니다.`,
  Zb = `해당 자산에 대해 지원되지 않는 파일 유형입니다.`,
  Qb = `최대 파일 크기(%1$s)를 초과합니다.`,
  $b = `최종 이미지`,
  ex = `이 작업은 해당 유형의 현지화된 아트워크를 모두 제거합니다. 반드시 이벤트를 저장한 후 적용해야 합니다. 계속 진행할까요?`,
  tx = `[마지막 업데이트: %1$s]`,
  nx = `지원 언어`,
  rx = `추가 언어`,
