  ax = `베타 기간 동안 이벤트 및 공지 기능이 어떻게 작동하는지에 대한 자세한 정보 및 주의 사항은 문서를 참조하세요.`,
  ox = `피드백: 보고하실 버그나 궁금하신 문의 사항 또는 의견이 있으신가요? %1$s에 메시지를 게시하거나, Steam 계정 관리자에게 언제든지 연락해 주세요.`,
  sx = `Steamworks 포럼`,
  cx = `그 외 다수 기능 추가 예정`,
  lx = `공개 베타 기간에는 이 버전이 귀사와 귀사의 팀에게만 표시됩니다. Steam 고객들에게는 이벤트 및 공지가 기존 버전으로 표시됩니다.`,
  ux = `세부 정보 및 요령`,
  dx = `이벤트 아트워크 템플릿 다운로드`,
  fx = `이제 막 시작하셨나요? 예시를 참고하세요.`,
