  mx = `크기`,
  hx = `모든 로고와 텍스트는 중앙의 800px 이내에 위치해야 합니다.`,
  gx = `로고`,
  _x = `파일 이름의 끝 부분에 언어명을 추가한 파일(예: header_french.jpg)을 업로드하면, 해당 언어로 자동 분류됩니다. %1$s에서 지원되는 언어의 목록을 확인하세요.`,
  vx = `지역화`,
  yx = `아래 상자에 파일을 끌어다 놓거나 '파일 선택' 버튼을 클릭하면 여러 개의 파일을 업로드할 수 있습니다.`,
  bx = `이미지 업로드`,
  xx = `이미지 1개 관리`,
  Sx = `이미지 %1$s개 관리`,
  Cx = `고급 헤더 이미지를 상세 정보 페이지에 추가하여 업데이트 및 공지의 테마 또는 주요 내용을 공유하세요. 참고로 이 페이지 상단에 링크되어 있는 템플릿을 다운로드하여 헤더 이미지가 다양한 상황에서 적절히 사용될 수 있도록 디자인되어 있는지 확인하는 것이 중요합니다.`,
  wx = `상세 정보 페이지 미리 보기:`,
  Tx = `이벤트 팝업 페이지 미리 보기:`,
  Ex = `이 이미지는 방송 화면 옆의 사이드 패널에 표시됩니다.`,
  Dx = `중요한 이벤트 또는 공지는 이벤트 기간 중 상점 페이지에 표시되는 배너 이미지를 포함할 수 있습니다. 이 배너의 아트워크는 상점 내 다른 공간에 있는 아트워크와는 별개이며 이러한 배너는 Valve의 승인을 받아야 합니다. 업로드 전에 Valve 담당자에게 문의하세요.`,
  Ox = `집중 조명 배너에 이벤트에 대한 간략하고 눈에 띄는 설명을 추가하면 플레이어들이 이벤트의 흥미로운 부분을 한눈에 확인할 수 있습니다.`,
  kx = `이미지 전체 공간을 사용하여 이미지 내에 업데이트 또는 이미지에 대한 설명을 포함할 수 있습니다.`,
  Ax = `위의 상점 집중 조명 섹션의 모바일 버전으로 사용자가 좁은 화면으로 섹션을 볼 때 사용됩니다.`,
  jx = `이 이미지는 할인 페이지의 배경으로 표시됩니다. 하나의 큰 이미지로 사용하거나 타일로 만들어 반복적인 패턴으로 배열할 수 있습니다.`,
  Mx = `중요한 콘텐츠는 이미지 중앙에 940px 너비 영역 내에 배치되어야 합니다. 아트워크는 원하는 대로 페이지의 측면과 하단으로 이동할 수 있습니다. 일반적으로 아트워크는 페이지의 측면과 하단에서 단색으로 페이드 처리되도록 하고, 페이지를 일치하는 배경색으로 지정합니다. 이미지 크기는 4MB 이하로 유지하세요.`,
  Nx = `모든 할인 페이지 템플릿(.psd 파일) 다운로드`,
  Px = `할인 배경 이미지는 아래 지정된 할인 페이지 로고와 함께 사용하는 것이 좋습니다. 함께 사용하면 판매 페이지 로고가 배경 위에 표시됩니다.`,
  Fx = `템플릿`,
  Ix = `이 이미지는 페이지의 상단의 배경 위에 겹쳐 표시됩니다. 지역화된 이미지를 원하시면 Valve 담당자에게 .psd 파일을 이메일로 제출하시기 바랍니다.`,
  Lx = `제공된 배너는 할인 이벤트에 참가하는 모든 게임의 상점 페이지에 표시됩니다. 배너는 할인 이벤트가 진행되는 기간 동안(최대 2주) 표시됩니다. 배너는 사용 전에 반드시 Valve의 승인을 받아야 하며 애니메이션을 사용할 수 없습니다.`,
  Rx = `이 버전은 모바일 디스플레이에서 페이지 해상도가 낮아진 경우에만 표시됩니다.`,
  zx = `브랜딩이 포함된 라이브러리 히어로 이미지를 업데이트, 공지, 시즌, 또는 다른 이벤트를 위해 업데이트할 수 있습니다. 이는 상점 페이지 관리의 '그래픽 자산' 탭에서 진행할 수 있습니다.`,
  Bx = `디자인`,
  Vx = `크기`,
  Hx = `용도`,
  Ux = `필수`,
  Wx = `선택 사항`,
  Gx = `이 이미지는 일반적으로 이벤트를 나타내는 아트워크와 브랜드 로고 그리고 짧은 메시지를 포함합니다. Steam 내 일부 공간에서는 게임의 이름과 아이콘이 이미지 옆에 자동으로 함께 표시되지만, 이벤트를 소셜 미디어에서 공유할 때 이 이미지가 사용되므로 표지 이미지 게임 로고를 포함하는 것도 좋습니다.`,
  Kx = `이 이미지는 상점 페이지의 최근 공지 섹션, 이벤트 및 공지 목록, 라이브러리의 게임 상세 페이지에 표시됩니다. 소셜 미디어에서 이벤트 공유 시 대표 이미지로 사용됩니다. 이벤트 및 공지로 연결하는 링크를 표시할 때도 사용되며, 다른 여러 게임 콘텐츠와 나란히 표시될 수 있으므로 선명하고 알아보기 쉬워야 합니다.`,
  qx = `이 이미지는 일반적으로 개발사, 배급사, 프랜차이즈의 아트워크와 브랜드 로고를 포함합니다. Steam 내 일부 공간에서는 아바타 아이콘이 이 이미지 옆에 자동으로 함께 표시됩니다.`,
  Jx = `이 이미지는 Steam 내 제작자 홈이 표시되는 공간에 표시되며, 소셜 미디어에서 이벤트 공유 시 대표 이미지로 사용되므로 선명하고 알아보기 쉬워야 합니다.`,
  Yx = `Steam 차트의 올해의 최고 인기 게임 링크 배너 이미지`,
  Xx = `이 이미지는 '할인 및 이벤트' 페이지 등 해당 할인의 교차 프로모션 섹션에서 할인 페이지 로고 대신 표시됩니다. 이 로고에 대한 현지화가 필요하지 않은 경우 영어 버전을 한 번만 업로드하면 모든 언어에서 해당 이미지가 사용됩니다.`,
  Zx = `할인 페이지 상단 영역의 배경 이미지 위에 렌더링되는 로고입니다. 이 이미지는 투명한 배경에 이벤트 로고, 날짜, 소개 문구가 포함되어야 합니다.`,
  Qx = `이 문서`,
  $x = `이미지 미리 보기`,
  eS = `이미지 업로드`,
  tS = `업로드한 언어`,
  nS = `다른 언어에 이 이미지 지정`,
  rS = `새 창에서 이 이미지 열기`,
  iS = `이 언어만 이미지 삭제`,
  aS = `선택된 이미지 없음`,
  oS = `위의 업로더 사용`,
  sS = `언어 없음`,
  cS = `파일 선택`,
  lS = `목록에서 이미지 삭제`,
  uS = `지역화 언어 %1$s의 이벤트 제목 아트워크에서 이미지를 삭제할까요? 원본 이미지는 삭제되지 않으며, 이벤트와의 연관성만 제거됩니다.`,
  dS = `이미지에 표시된 빨간 사각형은 로고와 텍스트가 배치되어야 할 영역을 나타냅니다. 이벤트 목록과 같이, 특정 환경에서는 이 부분만 표시됩니다.`,
  fS = `축소의 예시`,
  pS = `이 잘라낸 이미지 버전은 여러 이벤트의 그리드 또는 목록 형식 표시에 사용됩니다.`,
