  vS = `라이브러리에 표시되는 이벤트!`,
  yS = `저장하지 않고 계속 진행`,
  bS = `아트워크 언어 업데이트`,
  xS = `이 아트워크에 다른 언어를 지정할 수 있습니다`,
  SS = `이벤트 제목`,
  CS = `이벤트 부제`,
  wS = `이벤트 날짜`,
  TS = `이벤트 세부 정보 및 본문 내용`,
  ES = `아트워크의 최소 크기는 1920x800(높이 x 너비)입니다. 높이나 너비는 더 커도 됩니다.`,
  DS = `앱 메타데이터 수정`,
  OS = `디포 업로드, Steamworks 기능 테스트, 패키지, 도전 과제 및 순위표 정의, 트레이딩 카드 게시 등의 기능을 사용할 수 있습니다. 또한 그룹의 모든 애플리케이션과 관련된 Steam 커뮤니티에서 관리자 권한과 지정 권한이 부여됩니다.`,
  kS = `Steam에 앱 변경 사항 게시`,
  AS = `Steamworks 개발자 사이트의 기술적 도구 > Steamworks 설정 변경 섹션에서 적용한 타이틀 변경 사항을 게시할 수 있습니다.`,
  jS = `오류 데이터 보기`,
  MS = `타이틀이 Steamworks 오류 보고 시스템에 통합되어 있는 경우, 해당 타이틀에 대한 오류 보고서를 열람할 수 있는 권한을 부여합니다.`,
  NS = `Steam을 통해 게임 다운로드하기`,
  PS = `CD 키 업로드`,
  FS = `Steam 키 생성`,
  IS = `앱에 대한 CD 키 배치를 요청하거나 타사 키를 업로드할 수 있습니다.`,
  LS = `재무 정보 보기`,
  RS = `애플리케이션 및 패키지의 판매 현황을 열람하고 데이터를 다운로드할 수 있습니다.`,
  zS = `게임 CEG 관리`,
  BS = `타이틀의 CEG 설정 및 통합을 관리할 수 있습니다.`,
  VS = `서명 관리`,
  HS = `게임에 대한 디지털 서명을 관리할 수 있습니다. 이를 통해 애플리케이션의 부정행위 방지 및 SDK 인증 설정을 관리할 수 있습니다.`,
  US = `CD 키 관리`,
  WS = `앱 마케팅 데이터 수정`,
  GS = `게임 설명, 브랜딩 이미지 및 동영상과 같은 상점 페이지 데이터를 수정하고 게시하는 권한을 부여합니다. 또한, 노출 라운드와 같은 마케팅 도구도 사용할 수 있습니다.`,
  KS = `상점 현지화 데이터 수정`,
  qS = `제품 설명 및 그래픽 자산과 같은 현지화가 가능한 항목을 1개 이상 포함한 상점 콘텐츠의 모든 데이터를 편집할 수 있는 권한을 지정합니다. 노출 라운드와 같은 마케팅 도구 이용 또는 게시에 대한 권한은 없습니다. 참고로 이것은 '앱 마케팅 데이터 수정' 기능의 하위 기능입니다.`,
  JS = `경제 및 창작마당 지원`,
  YS = `사용자가 파트너 사이트 경제 지원 도구에서 경제 아이템을 열람하고 등록할 수 있도록 허용합니다.`,
  XS = `경제 및 창작마당 감독`,
  ZS = `현재 상단의 경제/창작마당 지원과 같은 기능을 제공합니다.`,
  QS = `가격 및 할인 관리`,
  $S = `사용자가 가격 변경을 제안하고 할인 및 프로모션 행사에 참여할 수 있습니다.`,
  eC = `라이브 방송`,
  tC = `사용자가 앱의 공식 라이브 스트리밍을 방송할 수 있습니다.`,
  nC = `마케팅 트래픽 데이터 보기`,
  rC = `타이틀의 Steam 상점, 커뮤니티 및 플랫폼 내비게이션 트래픽 데이터를 확인할 수 있습니다.`,
  iC = `사용자 관리`,
  aC = `배급사 전체: 이 사용자는 다른 사용자를 추가하고 승급시킬 수 있습니다.`,
  oC = `실제 결정권자`,
