  BT = `고객이 제작자 홈페이지에서 할인 페이지로 접속할 때 할인 페이지 URL의 끝부분에 사용됩니다. 공백을 포함하면 URL 인코딩이 URL을 읽기 어렵게 되므로, 밑줄 문자(_)를 대신 사용하는 것이 좋습니다. 입력란에는 문자, 숫자, 밑줄 문자(_) 및 줄표(-)만 사용할 수 있습니다.  예: Halloween2019, Valentines, BestSaleEver`,
  VT = `업데이트 랜딩 페이지 맞춤 ID 및 URL`,
  HT = `고객을 업데이트 랜딩 페이지로 안내하는 상점 페이지 URL 끝에 사용됩니다. 공백을 포함하지 마세요. URL 인코딩 시 공백은 특수 문자로 변환되어 가독성이 떨어지므로 밑줄(_)을 대신 사용하는 것이 좋습니다. 문자, 숫자, 밑줄(_), 붙임표(-)만 사용할 수 있습니다.(예: Halloween2019, Valentines, BestSaleEver) `,
  UT = `이벤트 시작 시 사용할 링크`,
  WT = `이벤트 시작 시 Steam 상점에 특집으로 노출`,
  GT = `섹션 제목을 대문자로 표시하지 마세요`,
  KT = `기본적으로 모든 섹션의 제목은 대문자로 작성됩니다. 이 옵션을 선택하면 해당 설정이 비활성화되므로 섹션의 제목을 각 언어에 맞게 대소문자를 혼합하여 작성할 수 있습니다.`,
  qT = `광고 앱 ID`,
  JT = `이 페이지에 대한 광고 앱 ID를 지정하면 이 광고 앱과 연결된 모든 상점 내비게이션을 추적합니다.`,
  YT = `(Valve 전용) steampowered.com/sale 경로 사용`,
  XT = `파트너가 선택한 베니티 URL(상단)을 Steam 상점의 최상위 레벨 할인 페이지에 사용할 수 있게 해줍니다. 즉, 저희는 제작자 홈페이지뿐만이 아니라 할인 페이지를 호스트하고 홍보하고 추천합니다.`,
