  aE = `이 섹션은 어떤 유형이어야 하나요?`,
  oE = `이러한 설정은 랜딩 페이지에서 공개 여부를 제어하며, 섹션 내의 모든 데이터를 전송하므로 메모리를 검사하는 사용자가 데이터를 볼 수 있습니다. 즉, 실제로 데이터를 숨기지는 않습니다.`,
