  hE = `Steam Next Fest 탐색 모드에 따라 섹션 표시`,
  gE = `맞춤형 정렬은 무작위 정렬 대기 시간이 지난 후 사용자에게 추천할 게임이 있을 때 사용할 수 있습니다. 맞춤형 정렬을 사용할 수 있는 경우에도 사용자는 무작위 정렬로 전환할 수 있습니다. 맞춤형 정렬을 사용할 수 없으면 페이지는 항상 무작위 순서로 표시됩니다.`,
  _E = `모든 모드(항상 표시)`,
  vE = `'맞춤형' 모드에서만 표시`,
  yE = `사용자가 '무작위' 모드를 선택한 경우에도 '맞춤형' 모드를 사용할 수 있을 때만 표시`,
  bE = `'맞춤형' 모드를 사용할 수 없을 때만 표시`,
  xE = `모두 검색 버튼 표시`,
  SE = `제공된 링크는 이름을 링크로 바꾸도록 기본 설정되어 있지만, 이 옵션을 설정하면 '모두 검색' 버튼을 이름 영역에 추가됩니다`,
  CE = `탭 ID 필터링 끄기`,
  wE = `이 옵션을 선택하면 활성 탭에서 수행되는 일반 ID 필터링을 건너뜁니다. 사용자의 찜 목록에 있는 모든 항목과 같은 모든 앱을 여러 탭의 섹션에 표시하려는 경우, 이 옵션을 사용할 수 있습니다.`,
  TE = `그리드 설정`,
  EE = `표시 설정`,
  DE = `이 섹션 최소화하기`,
  OE = `이 섹션 최대화하기`,
  kE = `모든 할인 섹션 최소화하기`,
  AE = `솔로 모드`,
  jE = `이 모드를 사용하면 특정 할인 섹션 확장 시 다른 모든 섹션이 자동으로 축소됩니다.`,
  ME = `제목 변경`,
  NE = `내부용 이름`,
  PE = `선택적으로 사용할 수 있는 참고용 내부 이름으로 페이지에는 표시되지 않아 고객이 볼 수 없으며 섹션 헤더와 콘텐츠 표에 표시됩니다.`,
