  fD = `탭`,
  pD = `이 탐색 컨트롤에 표시되는 탭의 목록과 순서를 보여줍니다`,
  mD = `비활성화된 탭`,
  hD = `표시를 위해 추가하지 않는 한, 이 구성 요소에 사용되지 않는 추가 탭입니다`,
  gD = `이벤트 - %1$s`,
  _D = `< 유형을 선택해 주세요 >`,
  vD = `앱 및 꾸러미`,
  yD = `이 섹션은 게임, 패키지, 꾸러미를 페이지에 표시하는 데 사용됩니다. 여러 섹션을 만들고 각 섹션에 서로 다른 게임을 포함하는 것이 좋습니다.`,
