  wD = `이미지`,
  TD = `하나 이상의 이미지를 단일 항목, 회전식 또는 격자형으로 표시합니다. 선택적으로 현지화된 이미지를 제공할 수 있으며 이미지를 상점 내 다른 페이지와 연결할 수 있습니다.`,
  ED = `하나 이상의 이미지를 단일 항목, 회전식 또는 격자형으로 표시합니다. 선택적으로 현지화된 이미지를 제공할 수 있습니다.`,
  DD = `제목/헤더 이미지`,
  OD = `현지화할 수 있는 단일 이미지를 제목 또는 헤더에 표시합니다.`,
  kD = `교차 프로모션 할인 페이지`,
  AD = `이 위젯은 같은 시기에 활성화되어 있는 관련 할인 페이지에서 게임을 자동으로 가져옵니다. 콘텐츠가 할인 페이지 테마와 관련이 있는지 확인하세요.`,
