  qD = `전체 제작자 목록 표시`,
  JD = `제작자 홈 설정의 관리 목록 섹션에 정의된 모든 제작자 목록을 회전식으로 표시합니다.`,
  YD = `큐레이터 추천 및 목록`,
  XD = `큐레이터 추천 또는 추천 목록이 페이지에 표시되는 위치를 제어합니다. Steam 큐레이터를 팔로우하는 사용자는 할인 페이지 하단에서 할인 이벤트에 포함된 게임에 대한 큐레이터의 추천을 확인할 수 있습니다. 이 옵션을 사용하면 섹션이 표시되는 위치를 제어할 수 있습니다.`,
  ZD = `큐레이터 추천 및 목록을 표시합니다. Steam 사용자가 팔로우하는 큐레이터 목록과 Steam 사용자가 팔로우하는 언어로 된 추천 목록을 자동으로 가져옵니다.`,
  QD = `선택 사항: 공개 시작 시간`,
