  nO = `추천 목록 선택`,
  rO = `큐레이터는 이 할인 이벤트에서 추천할 게임 목록을 만들 수 있습니다. 이 대화 상자를 통해 페이지에서 소개할 추천 목록을 하나 이상 선택할 수 있습니다. 추천 목록은 페이지를 방문하는 모든 Steam 사용자에게 표시됩니다.`,
  iO = `큐레이터를 선택할 수 없습니다. 할인 이벤트가 공개되고 시작되어야 합니다.`,
