  sO = `탭 버튼`,
  cO = `옵션 섹션은 기본 탭이 있는 경우에만 유용합니다. 페이지 하단에 배치하면 탭이 버튼으로 교체되어, 페이지의 탭을 보지 못하고 지나칠 수도 있는 사용자가 쉽게 탐색하는 데 도움이 됩니다.`,
  lO = `객관식 질문`,
  uO = `고객이 경험할 수 있는 객관식 질문과 같은 몇 가지 상식 문제들을 만들 수 있는 섹션입니다.`,
